package net.civeira.phylax.features.access.userconsentedscopes.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ScopeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property scope of user consented scopes ")
  void test_scope_v_o_builder() {
    Assertions.assertFalse(ScopeVO.nullValue().getScope().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ScopeVO.tryFrom(null).getScope().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ScopeVO.from("one").getScope().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ScopeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ScopeVO.from("one").toString());
  }
}
